INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e', 'U_128194', '792ad3361e59e53c8f9429ade9bda9c91daef1938a04d82a9594cc614c153008', '8acd4495d1663cd05112f99ff359a881362f97810afaa5656c6f6b87820cb752', true, 'saved_analysis', NULL, '[{"kind": "saved_analysis"}]', '["energy", "logistics"]', 'low', 'ready', 'Основной ОКВЭД компании — торговля автодеталями, а новость касается логистики нефти. Косвенная экспозиция через топливных контрагентов крайне мала (1.14%) и не имеет установленной связи с рынком фрахта.', '[{"quote": "Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов", "source_id": "company:U_128194:okved_names"}, {"quote": "\"okved_code\": \"46.71\", \"okved_name\": \"Торговля оптовая твердым, жидким и газообразным топливом и подобными продуктами\", \"counterparties_count\": 6, \"amount_rub\": 62493000, \"share_pct\": 1.14", "source_id": "metric:U_128194:top_okved"}, {"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]', 'analysis', 0, 'ready', '2b353f51aedf44da8f9e589b8202d9ea', '{"mode": "live", "as_of": "2026-10-22T13:45:06.870942+00:00", "brief": {"status": "ready", "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "evidence": {"importance": [{"quote": "Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов", "source_id": "company:U_128194:okved_names"}, {"quote": "\"okved_code\": \"46.71\", \"okved_name\": \"Торговля оптовая твердым, жидким и газообразным топливом и подобными продуктами\", \"counterparties_count\": 6, \"amount_rub\": 62493000, \"share_pct\": 1.14", "source_id": "metric:U_128194:top_okved"}, {"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}], "news_summary": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}], "short_answer": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов", "source_id": "company:U_128194:okved_names"}, {"quote": "\"okved_code\": \"46.71\", \"okved_name\": \"Торговля оптовая твердым, жидким и газообразным топливом и подобными продуктами\", \"counterparties_count\": 6, \"amount_rub\": 62493000, \"share_pct\": 1.14", "source_id": "metric:U_128194:top_okved"}, {"quote": "Роли покупателя/поставщика и причинная связь с новостью не установлены.", "source_id": "metric:U_128194:top_okved"}]}, "company_id": "U_128194", "news_summary": "Аренда судов для перевозки сырья из Новороссийска и Приморска достигла исторического максимума в $27–48 за баррель. Это, наряду со снижением спроса в Азии, ведет к расширению дисконтов на российскую нефть.", "short_answer": "Прямая связь с деятельностью компании не подтверждена, так как она занимается оптовой торговлей автозапчастями. Возможна лишь слабая косвенная связь через контрагентов в сфере торговли топливом.", "classification": {"topics": ["energy", "logistics"], "importance": "low", "business_relevant": true, "importance_method": "classifier", "importance_reason": "Основной ОКВЭД компании — торговля автодеталями, а новость касается логистики нефти. Косвенная экспозиция через топливных контрагентов крайне мала (1.14%) и не имеет установленной связи с рынком фрахта."}}, "event": {"id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "url": "https://www.kommersant.ru/doc/9044169", "text": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти. По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель. В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть. Однако, при этом мировые цены на нефтепродукты сохраняются на высоком уровне. В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты. Подробности — в материале «У фрахта глаза велики» .", "title": "Ставки на перевозку российской нефти выросли до рекордного уровня", "topics": [], "regions": [], "countries": [], "published_at": "2026-10-21T16:14:44+00:00"}, "trace": [{"tool": "get_company_metrics", "cached": false, "status": "found", "arguments": {}, "source_ids": ["metric:U_128194:top_okved", "metric:U_128194:counterparties", "metric:U_128194:totals"]}, {"tool": "search_news", "cached": false, "status": "found", "arguments": {"query": "автозапчасти оптовые продажи"}, "source_ids": ["news:979c31165ea59654907f85e01f2977b9b466dd2589ba8a9b4ff87f9feb4d2d25", "news:ca9b8b908ca919199a8c6c3d95d1bee5b77dcaa38b6be2d38f782abafd2a7ca5", "news:8e51d67342b0e801ee2add6a2a595aa239cbd27a4a413c350c6e3da4839a79ae"]}, {"tool": "search_news", "cached": false, "status": "found", "arguments": {"query": "ставки фрахт перевозки нефти"}, "source_ids": ["news:742c81563bbb9a4a170062f93af9d1a556e159e070b75f6400e7620ede26ca10", "news:979c31165ea59654907f85e01f2977b9b466dd2589ba8a9b4ff87f9feb4d2d25", "news:35b96e76fbd32900239619f2a3c327e718ad47c05aca6cfc7a0f0cc78c3f01b6"]}, {"tool": "search_bank_analytics", "cached": false, "status": "unavailable", "arguments": {"query": "автомобильные запчасти авторынок отрасль"}, "source_ids": []}, {"tool": "search_bank_analytics", "cached": true, "status": "unavailable", "arguments": {"query": "логистика фрахт нефть ставки"}, "source_ids": []}], "result": {"claims": [{"kind": "fact", "text": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "evidence": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть.", "evidence": [{"quote": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты.", "evidence": [{"quote": "В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "Основной ОКВЭД компании — 45.31.1 «Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов».", "evidence": [{"quote": "Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов", "source_id": "company:U_128194:okved_names"}]}, {"kind": "fact", "text": "Среди контрагентов компании по агрегатам платежей присутствует ОКВЭД 46.71 «Торговля оптовая твердым, жидким и газообразным топливом и подобными продуктами» с долей 1.14%.", "evidence": [{"quote": "\"okved_code\": \"46.71\", \"okved_name\": \"Торговля оптовая твердым, жидким и газообразным топливом и подобными продуктами\", \"counterparties_count\": 6, \"amount_rub\": 62493000, \"share_pct\": 1.14", "source_id": "metric:U_128194:top_okved"}]}, {"kind": "hypothesis", "text": "Прямая применимость новости к компании не подтверждается: новость касается перевозки нефти, тогда как основной вид деятельности компании — оптовая торговля автозапчастями.", "evidence": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов", "source_id": "company:U_128194:okved_names"}]}, {"kind": "hypothesis", "text": "Возможна косвенная экспозиция через контрагентов в оптовой торговле топливом, однако роли и причинная связь с новостью не установлены.", "evidence": [{"quote": "\"okved_code\": \"46.71\", \"okved_name\": \"Торговля оптовая твердым, жидким и газообразным топливом и подобными продуктами\", \"counterparties_count\": 6, \"amount_rub\": 62493000, \"share_pct\": 1.14", "source_id": "metric:U_128194:top_okved"}, {"quote": "Роли покупателя/поставщика и причинная связь с новостью не установлены.", "source_id": "metric:U_128194:top_okved"}]}], "status": "supported", "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "summary": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель. Прямая применимость новости к компании не подтверждается: новость касается перевозки нефти, тогда как основной вид деятельности компании — оптовая торговля автозапчастями.", "company_id": "U_128194", "missing_data": ["Нет данных о наличии у компании деятельности, связанной с перевозкой или торговлей нефтью.", "Нет данных о доле выручки или платежей, приходящейся на контрагентов топливного сектора.", "Нет сведений о влиянии ставок фрахта на перевозку нефти на финансовые или операционные показатели компании.", "Ограничение получения контекста: search_bank_analytics (unavailable)"], "follow_up_answer": null}, "company": {"id": "U_128194", "provenance": "dataset", "source_ref": "docs/companies/companies_analytics.json#U_128194", "okved_codes": ["45.31.1"], "okved_names": ["Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов"], "ownership_form": "ЧАСТНАЯ СОБСТВЕННОСТЬ", "trade_countries": null, "banking_services": ["РКО", "Кредиты", "Зарплатный проект"], "development_stage": "Оптимизация", "annual_revenue_rub": 7282655891.0, "registration_region": "Воронежская область"}, "history": [], "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "ranking": {"score": 0, "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "reasons": [], "eligible": true, "company_id": "U_128194", "missing_data": ["trade_countries", "confirmed_business_exposure"]}, "telemetry": [{"task": "brief", "model": "google/gemma-4-26b-a4b-it", "usage": {"cost": 0.018692007090900003, "total_tokens": 2270, "prompt_tokens": 1971, "completion_token