alse, "locator": "docs/companies/companies_analytics.json#U_46911/payments/totals", "publisher": null, "source_id": "metric:U_46911:totals", "company_id": "U_46911", "collected_at": null, "published_at": "2026-10-22T09:22:47+00:00"}, {"url": "https://www.interfax.ru/business/1124059", "kind": "news", "text": "Инфляция в РФ с 13 по 19 октября составила 0,05%, годовая замедлилась до 7,15%\nМосква. 21 октября. INTERFAX.RU - Инфляция в РФ с 13 по 19 октября составила 0,05% после 0,11% с 6 по 12 октября, 0,96% с 29 сентября по 5 октября (\"тарифная неделя\" после индексации с 1 октября стоимости услуг ЖКХ), 0,12% с 22 по 28 сентября, 0,06% с 15 по 21 сентября, 0,02% с 8 по", "title": "Инфляция в РФ с 13 по 19 октября составила 0,05%, годовая замедлилась до 7,15%", "is_demo": false, "locator": "https://www.interfax.ru/business/1124059", "publisher": "Интерфакс", "source_id": "news:266d96677a4999c468e5642e31cd0a9909608a4c44310d47c5f2ad2e7bfe3910", "company_id": null, "collected_at": "2026-10-21T19:59:57.683146+00:00", "published_at": "2026-10-21T16:03:00+00:00"}, {"url": "https://www.interfax.ru/business/1124072", "kind": "news", "text": "Рубль укрепляется к мировым валютам четвертый день подряд\nМосква. 21 октября. INTERFAX.RU - Китайский юань умеренно снизился на Московской бирже по итогам торгов в среду. Курс рубля укрепился к основным мировым валютам четвертый торговый день подряд на фоне высоких мировых цен на нефть и приближающегося налогового периода октября.\n\nСтоимость юаня по данным на 19:00 составила 12,2255 рубля, что на 11,95 копейки (на 0,97%) ниже уровня", "title": "Рубль укрепляется к мировым валютам четвертый день подряд", "is_demo": false, "locator": "https://www.interfax.ru/business/1124072", "publisher": "Интерфакс", "source_id": "news:742c81563bbb9a4a170062f93af9d1a556e159e070b75f6400e7620ede26ca10", "company_id": null, "collected_at": "2026-10-21T19:59:43.597087+00:00", "published_at": "2026-10-21T16:54:00+00:00"}, {"url": "https://www.kommersant.ru/doc/9044169", "kind": "news", "text": "Ставки на перевозку российской нефти выросли до рекордного уровня\nРост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти. По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель. В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть. Однако, при этом мировые цены на нефтепродукты", "title": "Ставки на перевозку российской нефти выросли до рекордного уровня", "is_demo": false, "locator": "https://www.kommersant.ru/doc/9044169", "publisher": "Коммерсантъ", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "company_id": null, "collected_at": "2026-10-21T19:59:58.568791+00:00", "published_at": "2026-10-21T16:14:44+00:00"}]}', '2026-10-22 13:45:06.870942+00', NULL, '2026-10-23 17:26:13.378314+00', '2026-10-24 10:47:46.631516+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e', 'U_46827', '792ad3361e59e53c8f9429ade9bda9c91daef1938a04d82a9594cc614c153008', '4566cd9e6185ca26a7c9951bef9937c3ef8d4124997006a39c2270f778793396', true, 'hybrid', 0.09475806, '[{"kind": "industry", "okved": "52.29", "query": "Транспортная логистика, порты, грузоперевозки и ставки фрахта", "lexical_query": "\"перевозки\" OR \"грузоперевозки\" OR \"пароходства\" OR \"порты\" OR \"фрахт\""}]', '["energy", "logistics"]', 'low', 'ready', 'Связь слабая, так как компания занимается вспомогательной деятельностью (ОКВЭД 52.29), а новость касается непосредственно стоимости аренды судов для нефти.', '[{"quote": "[\"Деятельность вспомогательная прочая, связанная с перевозками\"]", "source_id": "company:U_46827:okved_names"}, {"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]', 'analysis', 0, 'partial', '78f0dc55be1d4cc898de618c0ec72b7b', '{"mode": "live", "as_of": "2026-10-23T17:31:36.968589+00:00", "brief": {"status": "ready", "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "evidence": {"importance": [{"quote": "[\"Деятельность вспомогательная прочая, связанная с перевозками\"]", "source_id": "company:U_46827:okved_names"}, {"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}], "news_summary": [{"quote": "аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}], "short_answer": [{"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "[\"Деятельность вспомогательная прочая, связанная с перевозками\"]", "source_id": "company:U_46827:okved_names"}]}, "company_id": "U_46827", "news_summary": "Ставки фрахта на перевозку российской нефти из Новороссийска и Приморска достигли исторического максимума — $27–48 за баррель.", "short_answer": "Рост ставок фрахта может повлиять на компанию, если она оказывает услуги в сегменте морских перевозок нефти, однако точный профиль деятельности не подтвержден.", "classification": {"topics": ["energy", "logistics"], "importance": "low", "business_relevant": true, "importance_method": "classifier", "importance_reason": "Связь слабая, так как компания занимается вспомогательной деятельностью (ОКВЭД 52.29), а новость касается непосредственно стоимости аренды судов для нефти."}}, "event": {"id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "url": "https://www.kommersant.ru/doc/9044169", "text": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти. По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель. В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть. Однако, при этом мировые цены на нефтепродукты сохраняются на высоком уровне. В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты. Подробности — в материале «У фрахта глаза велики» .", "title": "Ставки на перевозку российской нефти выросли до рекордного уровня", "topics": [], "regions": [], "countries": [], "published_at": "2026-10-21T16:14:44+00:00"}, "trace": [{"tool": "get_company_metrics", "cached": false, "status": "found", "arguments": {}, "source_ids": ["metric:U_46827:top_okved", "metric:U_46827:counterparties", "metric:U_46827:totals"]}, {"tool": "search_bank_analytics", "cached": false, "status": "found", "arguments": {"query": "ставки фрахта морские перевозки нефть"}, "source_ids": ["bank:alfa-bond-brief-2026-09-14#7512d2f7d36f2840", "bank:alfa-macro-1h26#5be166b212bfe1aa", "bank:alfa-policy-rate-2026-09-11#debf21113eb96a49"]}, {"tool": "search_bank_analytics", "cached": false, "status": "limited", "arguments": {"query": "транспорт логистика ставка кредитование"}, "source_ids": ["bank:alfa-fi-strategy-3q26#62f0ad597286116f", "bank:alfa-consumption#f2759ca34798df58"]}, {"tool": "search_news", "cached": false, "status": "limited", "arguments": {"query": "ставки фрахта перевозка нефти Новороссийск"}, "source_ids": []}, {"tool": "search_news", "cached": false, "status": "limited", "arguments": {"query": "дисконт российская нефть экспорт Азия"}, "source_ids": []}], "result": {"claims": [{"kind": "fact", "text": "Ставки фрахта на перевозку российской нефти из Новороссийска и Приморска достигли исторического максимума — $27–48 за баррель.", "evidence": [{"quote": "аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "Российская нефть испытывает расширение дисконтов из-за снижения спроса со стороны азиатских НПЗ.", "evidence": [{"quote": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "Основной заявленный ОКВЭД компании — 52.29 «Деятельность вспомогательная прочая, связанная с перевозками».", "evidence": [{"quote": "[\"Деятельность вспомогательная прочая, связанная с перевозками\"]", "source_id": "company:U_46827:okved_names"}]}, {"kind": "fact", "text": "Компания зарегистрирована в Москве; сведений о фактическом месте ведения операций в переданных данных нет.", "evidence": [{"quote": "\"Москва\"", "source_id": "company:U_46827:registration_region"}]}, {"kind": "fact", "text": "В платежных агрегатах контрагентов на ОКВЭД 52.29 приходится 25,94% оборота, но даты платежей и роли сторон не установлены.", "evidence": [{"quote": "{\"okved_code\": \"52.29\", \"okved_name\": \"Деятельность вспомогательная прочая, связанная с перевозками\", \"counterparties_count\": 34, \"amount_rub\": 263643000, \"share_pct\": 25.94", "source_id": "metric:U_46827:top_okved"}]}, {"kind": "hypothesis", "text": "Новость о росте ставок фрахта на перевозку российской нефти может быть релевантна компании, если она оказывает вспомогательные услуги в сегменте морских перевозок нефти, однако это не подтверждено: профиль содержит только ОКВЭД 52.29 и выручку, а новость описывает рынок перевозки нефти из Новороссийска и Приморска.", "evidence": [{"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "[\"Деятельность вспомогательная прочая, связанная с перевозками\"]", "source_id": "company:U_46827:okved_names"}]}], "status": "insufficient_data", "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "summary": "Данных для оценки влияния на компанию недостаточно. Ставки фрахта на перевозку российской нефти из Новороссийска и Приморска достигли исторического максимума — $27–48 за баррель. Новость о росте ставок фрахта на перевозку российской нефти может быть релевантна компании, если она оказывает вспомогательные услуги в сегменте морских перевозок нефти, однако это не подтверждено: профиль содержит только ОКВЭД 52.29 и выручку, а новость описывает рынок перевозки нефти из Новороссийска и Приморска.", "company_id": "U_46827", "missing_data": ["Сведения о фактических видах деятельности компании за пределами заявленного ОКВЭД 52.29", "Данные о причастности компании к морским перевозкам нефти или к портам Новороссийск/Приморск", "Роли компании и ее контрагентов (покупатель/поставщик) и причинная связь с новостью", "Операционная география и наличие экспортной деятельности", "Данные о структуре выручки по направлениям деятельности", "Ограничение получения контекста: search_bank_analytics (limited)", "Ограничение получения контекста: search_news (limited)"], "follow_up_answer": null}, "company": {"id": "U_46827", "provenance": "dataset", "source_ref": "docs/companies/companies_analytics.json#U_46827", "okved_codes": ["52.29"], "okved_names": ["Деятельность вспомогательная прочая, связанная с перевозками"], "ownership_form": "СОВМЕСТНАЯ ЧАСТНАЯ И ИНОСТРАННАЯ СОБСТВЕННОСТЬ", "trade_countries": null, "banking_services": ["cash_register", "credit", "payroll"], "development_stage": "Стремительный рост", "annual_revenue_rub": 2548893300.0, "registration_region": "Москва"}, "history": [], "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "ranking": {"score": 70, "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "reasons": [{"weight": 70, "feature": "okved_topic", "matched": ["logistics"]}], "eligible": true, "company_id": "U_46827", "missing_data": ["trade_countries"]}, "telemetry": [{"task": "classification", "model": "google/gemma-4-26b-a4b-it", "usage": null, "status": "LLM transport failure", "attempt": 1, "error_type": "OpenAIConnectionError", "latency_ms": 1693, "max_tokens": 1024, "cause_types": ["APIConnection