INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e', 'U_37452', '792ad3361e59e53c8f9429ade9bda9c91daef1938a04d82a9594cc614c153008', '286ce838a0e751641b85fb73a892b3987634ad3315d5e6220becf3c338bb7e03', true, 'company_embedding', 0.8140827417373657, '[{"kind": "semantic", "limitation": "Сходство определяет кандидатов, а не доказанное влияние.", "matched_topics": []}]', '["energy", "logistics"]', 'low', 'ready', 'Прямая связь не установлена: новость касается стоимости фрахта нефти, в то время как компания занимается торговлей электротоварами.', '[{"quote": "46.43", "source_id": "company:U_37452:okved_codes"}, {"quote": "Торговля оптовая бытовыми электротоварами", "source_id": "company:U_37452:okved_names"}, {"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]', 'analysis', 0, 'partial', '3c662e05485c469c85886170649cc964', '{"mode": "live", "as_of": "2026-10-22T13:45:06.870942+00:00", "brief": {"status": "ready", "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "evidence": {"importance": [{"quote": "46.43", "source_id": "company:U_37452:okved_codes"}, {"quote": "Торговля оптовая бытовыми электротоварами", "source_id": "company:U_37452:okved_names"}, {"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}], "news_summary": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}], "short_answer": [{"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "Торговля оптовая бытовыми электротоварами", "source_id": "company:U_37452:okved_names"}]}, "company_id": "U_37452", "news_summary": "Аренда судов для перевозки российской нефти из Новороссийска и Приморска достигла исторического максимума в $27–48 за баррель.", "short_answer": "Событие вряд ли повлияет на компанию, так как её деятельность связана с оптовой торговлей бытовыми электротоварами, а не с нефтяной логистикой.", "classification": {"topics": ["energy", "logistics"], "importance": "low", "business_relevant": true, "importance_method": "classifier", "importance_reason": "Прямая связь не установлена: новость касается стоимости фрахта нефти, в то время как компания занимается торговлей электротоварами."}}, "event": {"id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "url": "https://www.kommersant.ru/doc/9044169", "text": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти. По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель. В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть. Однако, при этом мировые цены на нефтепродукты сохраняются на высоком уровне. В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты. Подробности — в материале «У фрахта глаза 